#[test]
fn a_plain_stream_errors_walk_answers_as_jq_7571() -> Result<()> {
    let dir = tempfile::tempdir()?;
    let paths: Vec<String> = (0..2)
        .map(|n| {
            dir.path()
                .join(format!("p{n}.json"))
                .to_string_lossy()
                .into_owned()
        })
        .collect();
    let missing = dir
        .path()
        .join("missing.json")
        .to_string_lossy()
        .into_owned();
    let directory = dir.path().to_string_lossy().into_owned();
    let mut failures = Vec::new();
    for &(mode, program, input, stdout, stderr, status) in ROWS {
        let mut args: Vec<&str> = vec!["-c", "--stream-errors", program];
        let (output, code) = if mode == "stdin" {
            spawn_jq(&args, Some(input.as_bytes()))?
        } else {
            let parts = if mode == "split" || mode == "miss-between" {
                let half = input.len() / 2;
                vec![&input[..half], &input[half..]]
            } else {
                vec![input]
            };
            for (path, part) in paths.iter().zip(&parts) {
                std::fs::write(path, part)?;
                args.push(path);
            }
            match mode {
                "miss-after" => args.push(&missing),
                "miss-before" => args.insert(3, &missing),
                "miss-between" => args.insert(4, &missing),
                "dir-after" => args.push(&directory),
                _ => {}
            }
            spawn_jq(&args, Some(b""))?
        };
        let place = |text: &str| {
            // `DIR` first: a temporary path can hold the letters of another placeholder.
            text.replace("DIR", &directory)
                .replace("MISSING", &missing)
                .replace("FILE0", &paths[0])
                .replace("FILE1", &paths[1])
        };
        let got = (
            String::from_utf8_lossy(&output.stdout).into_owned(),
            String::from_utf8_lossy(&output.stderr).into_owned(),
            code,
        );
        let want = (place(stdout), place(stderr), status);
        if got != want {
            failures.push(format!(
                "{mode} {program:?} over {input:?}: got {got:?}, want {want:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} rows differ:\n{}",
        failures.len(),
        ROWS.len(),
        failures.join("\n")
    );
    Ok(())
}
